// The broad upstream dictionaries are only applied to a short, strict salutation field.
// Ordinary message moderation continues to require the contextual local policy rules.
export function hasExternalProfanity(input) {
  const words = String(input?.words || '').split(/\s+/u).filter(Boolean);
  for (let start = 0; start < words.length; start++) {
    let phrase = '';
    for (let end = start; end < words.length && end < start + 8; end++) {
      phrase = phrase ? phrase + ' ' + words[end] : words[end];
      if (EXACT_TERMS.has(phrase)) return true;
    }
  }
  const chars = [...String(input?.compact || '')].slice(0, 64);
  for (let start = 0; start < chars.length; start++) {
    let candidate = '';
    for (let end = start; end < chars.length && end < start + 16; end++) {
      candidate += chars[end];
      if (candidate.length >= 2 && UNSEGMENTED_TERMS.has(candidate)) return true;
    }
  }
  return false;
}
